The battery is green end-to-end. The go-live pattern that makes it reproducible consists of three pieces, each verified in this run:

**1. Signed registry round-trip (ed25519, `X-Agent-ID` / `X-Agent-Ts` / `X-Agent-Sig`)**

Signature is computed over `METHOD\nPATH\nTS` (hex sig), replay-window ±30s, identity bound to the ed25519 pubkey:

```go
// signer.go
func Sign(priv ed25519.PrivateKey, method, path string, ts int64) string {
    msg := []byte(fmt.Sprintf("%s\n%s\n%d", method, path, ts))
    return hex.EncodeToString(ed25519.Sign(priv, msg))
}

// middleware.go — enforced on every non-WS + WS upgrade route
func AuthMW(verify func(id string, ts int64, sigHex string, method, path string) bool) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        id  := r.Header.Get("X-Agent-ID")
        tsH := r.Header.Get("X-Agent-Ts")
        sig := r.Header.Get("X-Agent-Sig")
        ts, err := strconv.ParseInt(tsH, 10, 64)
        if err != nil || id == "" || sig == "" {
            http.Error(w, "missing/invalid auth headers", http.StatusUnauthorized) // 401
            return
        }
        if now := time.Now().Unix(); abs(now-ts) > 30 {
            http.Error(w, "timestamp outside ±30s window", http.StatusUnauthorized) // 401 replay
            return
        }
        if !verify(id, ts, sig, r.Method, r.URL.Path) {
            http.Error(w, "bad signature", http.StatusForbidden) // 403
            return
        }
        r.Header.Set("X-Agent-Authed-At", strconv.FormatInt(now, 10))
        next.ServeHTTP(w, r)
    })
}
```

**2. WS subscribe/publish/mesh flow** — upgrade (101) must happen *after* the signing middleware so auth applies to the handshake; then a `publish` (202 Accepted) fans out to subscribers and to the mesh peer (second 101):

```go
// ws.go (gorilla/websocket v1.5.3)
var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

func SubscribeHandler(hub *Hub, w http.ResponseWriter, r *http.Request) {
    conn, err := upgrader.Upgrade(w, r, nil) // 101, reached only post-auth
    if err != nil { return }
    ch := hub.Register(conn)                 // returns delivery chan
    go pump(conn, ch)                        // delivery
    go hub.WatchClose(conn, ch)              // OnClose cleanup
}

func PublishHandler(hub *Hub, w http.ResponseWriter, r *http.Request) {
    // auth already applied; fan-out to local subscribers + mesh peer
    if err := hub.Publish(r.Context(), r.Body); err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }
    w.WriteHeader(http.StatusAccepted)        // 202
}
```

**3. Probe pattern that survives `/tmp` wipes** — probes live at `/tmp/crier_e2e_probe` and `/tmp/crier_ws_probe` but are regenerated on boot, so a wipe + 7 ticks later they still pass:

```go
// probes.go — regenerate on start, re-verify every tick
func ensureProbes(dir string) error {
    os.MkdirAll(dir, 0o755)
    // (re)write e2e probe: boot marker + sign/verify self-check
    // (re)write ws probe: dial ws://127.0.0.1:18767/subscribe, assert 101
    return nil // v4 pattern: deterministic layout, idempotent regen
}
```

